// generated by scripts/p2v.py
#![allow(unused_variables)]
use neutral_world::{check, load};
use lift_a::p2v;
use std::path::PathBuf;

fn vec_path(name: &str) -> PathBuf {
    let dir = match std::env::var("PORTA_VECTORS") {
        Ok(d) => PathBuf::from(d),
        Err(_) => PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("..").join("vectors"),
    };
    dir.join(format!("{}.world.vec", name))
}

fn code() -> &'static [u8] {
    static CODE: std::sync::OnceLock<Vec<u8>> = std::sync::OnceLock::new();
    CODE.get_or_init(|| {
        let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        for _ in 0..8 {
            let p = dir.join("original").join("neutral_3.text.bin");
            if p.exists() {
                return std::fs::read(&p).unwrap();
            }
            if !dir.pop() {
                break;
            }
        }
        panic!("original/neutral_3.text.bin not found");
    })
}

#[test]
#[ignore = "needs the stored vectors from sapphire_archive.zip"]
fn f_00000000() {
    let vf = load(&vec_path("f_00000000")).unwrap();
    let rep = check(&vf, Some(code()), |w, c| {
        let r = p2v::f_00000000(w, c.int(0), c.int(1) as u32);
        vec![r.0 as u128, r.1 as u128]
    });
    println!("WORLD f_00000000 compared={} skipped={} failed={} rust_faults={}", rep.compared, rep.skipped, rep.failed, rep.rust_faults);
    rep.assert_ok(900);
}

